export function tr(locale:string,en:string,de?:string):string {if(locale==='en')return en;if(locale==='de')return de??en;const value=copy[locale]?.[en];if(value===undefined)throw new Error('Missing Robotics translation: '+locale+' / '+en);return value;}
export function getRoboticsUI(locale:string){return copy[locale]??{};}
